def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_opp = history[-1][1]
    last_me = history[-1][0]
    prev_me = history[-2][0] if n >= 2 else 'C'

    my_d = 0
    opp_d = 0
    for a, b in history:
        if a == 'D':
            my_d += 1
        if b == 'D':
            opp_d += 1

    start = n - 10
    if start < 0:
        start = 0
    recent_op_d = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            recent_op_d += 1

    win = 25
    if n < win:
        win = n
    start = max(1, n - win)

    cc = 0
    cd = 0
    dc = 0
    dd = 0
    for i in range(start, n):
        pm = history[i - 1][0]
        co = history[i][1]
        if pm == 'C':
            if co == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if co == 'C':
                dc += 1
            else:
                dd += 1

    pC = (cc + 4) / (cc + cd + 8)
    pD = (dc + 4) / (dc + dd + 8)

    if pC < 0.40 or recent_op_d >= 8 or (dc == 0 and cd >= 2):
        return 'D'

    if last_opp == 'D':
        if prev_me == 'D':
            if pC >= 0.50 and cd < 2 and recent_op_d <= 5:
                return 'C'
            return 'D'
        return 'D'

    if (prev_me == 'D' or last_me == 'D') and pD >= 0.54 and cd <= 2:
        return 'D'

    if n >= 30 and n < 90 and opp_d == 0 and my_d == 0:
        return 'D'

    return 'C'
